<?= $this->section('scripts') ?><script src="https://cdn.jsdelivr.net/npm/cropperjs@1.6.2/dist/cropper.min.js"></script><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/cropperjs@1.6.2/dist/cropper.min.css"><script>document.addEventListener('DOMContentLoaded',()=>{const inputs=document.querySelectorAll('input[type=file]');inputs.forEach(input=>{const preview=document.createElement('img');preview.className='kp-crop-preview';preview.style.cssText='display:none;max-width:100%;max-height:300px;margin-top:12px;border-radius:12px';input.closest('.col-12,.card-body')?.append(preview);input.addEventListener('change',()=>{const f=input.files[0];if(!f)return;preview.src=URL.createObjectURL(f);preview.style.display='block';new Cropper(preview,{aspectRatio:1,viewMode:1});});});});</script><?= $this->endSection() ?>